    @Published var isWatchPaired: Bool = false

    private var session: WCSession?

    override init() {
        super.init()
        print("[Taptic iPhone] 🔧 Initializing Watch Connectivity...")

        if WCSession.isSupported() {
            session = WCSession.default
            session?.delegate = self
            session?.activate()
            print("[Taptic iPhone] ✅ WCSession supported, activating...")
        } else {
            print("[Taptic iPhone] ❌ WCSession NOT supported on this device")
        }
    }

    /// Send sound detection to Apple Watch
    func sendSoundDetection(soundName: String, confidence: Double) {
        print("[Taptic iPhone] 📤 Attempting to send sound: \(soundName) (confidence: \(String(format: "%.2f", confidence)))")

        guard let session = session else {
            print("[Taptic iPhone] ❌ No WCSession available")
            return
        }

        print("[Taptic iPhone] Session state - activated: \(session.activationState == .activated), paired: \(session.isPaired), reachable: \(session.isReachable)")

        guard session.activationState == .activated else {
            print("[Taptic iPhone] ❌ Watch session not activated (state: \(session.activationState.rawValue))")
            return
        }

        // Check if watch is reachable for immediate message
        if session.isReachable {
            print("[Taptic iPhone] 📱 Watch is reachable, sending immediate message...")
            // Send immediate message (watch app is in foreground)
            let message: [String: Any] = [
                "soundName": soundName,
                "confidence": confidence,
                "timestamp": Date().timeIntervalSince1970
            ]

            session.sendMessage(message, replyHandler: { reply in
                print("[Taptic iPhone] ✅ Watch received sound alert: \(reply)")
            }, errorHandler: { error in
                print("[Taptic iPhone] ⚠️ Error sending immediate message: \(error.localizedDescription)")
                // Fall back to application context
                self.updateApplicationContext(soundName: soundName, confidence: confidence)
            })
        } else {
            print("[Taptic iPhone] ⏳ Watch not reachable, using application context...")
            // Watch app not in foreground, use application context (will sync when watch wakes)
            // applicationContext already provides guaranteed delivery — no need for transferUserInfo
            updateApplicationContext(soundName: soundName, confidence: confidence)
        }
    }

